public void processReport()
{
    next processReport(); // Call base logic

    // Additional updates
    this.updateProductReceiptId();
    this.updateBuyFromVendor();
    this.updateCatchWeightFields();
    this.updatePackSize();
    this.updateWeight();
    this.updateGSTAmount();
    this.updateCompany();
}

private void updateProductReceiptId()
{
    VendPackingSlipJour vendPackingSlipJour;
    VendAccruedPurchasesTmp vendAccruedPurchasesTmp = this.getVendAccruedPurchasesTmp();
    VendPackingSlipTrans    vendPackingSlipTrans;

    vendAccruedPurchasesTmp.ttsbegin();
    //update_recordSet vendAccruedPurchasesTmp
    //setting METPackingSlipId = vendPackingSlipJour.PackingSlipId
    //join vendPackingSlipJour
    //where vendPackingSlipJour.RecId == vendAccruedPurchasesTmp.PackingSlipSourceDocumentLine;

    update_recordSet vendAccruedPurchasesTmp
    setting METPackingSlipId = vendPackingSlipJour.PackingSlipId
        join vendPackingSlipTrans
            where vendPackingSlipTrans.sourceDocumentline == vendAccruedPurchasesTmp.PackingSlipSourceDocumentLine
        join vendPackingSlipJour
        where vendPackingSlipJour.RecId == vendPackingSlipTrans.VendPackingSlipJour;

    vendAccruedPurchasesTmp.ttscommit();
}

private void updateBuyFromVendor()
{
    PurchTable purchTable;
    VendTable   vendTable;
    DirPartyTable   dirPartyTable;
    VendAccruedPurchasesTmp vendAccruedPurchasesTmp = this.getVendAccruedPurchasesTmp();

    vendAccruedPurchasesTmp.ttsbegin();
    update_recordSet vendAccruedPurchasesTmp
    setting METOrderAccount = purchTable.OrderAccount, 
        METPurchName = dirPartyTable.Name
    join purchTable
    where purchTable.PurchId == vendAccruedPurchasesTmp.ReferenceId
        join vendTable
        where vendTable.AccountNum == purchTable.OrderAccount
        join dirPartyTable
        where dirPartyTable.RecId == vendTable.Party;
    vendAccruedPurchasesTmp.ttscommit();
}

private void updateCatchWeightFields()
{
    VendAccruedPurchasesTmp vendAccruedPurchasesTmp = this.getVendAccruedPurchasesTmp();
    /*
    update_recordSet vendAccruedPurchasesTmp
    setting METPdsCWQty = vendPackingSlipTrans.CatchWeightQty,
           METPdsCWUnitId = purchLine.CatchWeightUnitId
    join vendPackingSlipTrans
        where vendPackingSlipTrans.SourceDocumentLine == vendAccruedPurchasesTmp.PackingSlipSourceDocumentLine
    join purchLine
        where purchLine.PurchId == vendAccruedPurchasesTmp.ReferenceId
          && purchLine.ItemId == vendAccruedPurchasesTmp.ItemId;
    */
    PdsCatchWeightItem  pdsCatchWeightItem;
    VendPackingSlipTrans vendPackingSlipTrans;
    PurchLine   purchLine;
    vendAccruedPurchasesTmp.ttsbegin();
    update_recordSet vendAccruedPurchasesTmp
    setting METPdsCWQty = vendPackingSlipTrans.PdsCWQty,
           METPdsCWUnitId = pdsCatchWeightItem.PdsCWUnitId
    join vendPackingSlipTrans
        where vendPackingSlipTrans.SourceDocumentLine == vendAccruedPurchasesTmp.PackingSlipSourceDocumentLine
        join purchLine
        where purchLine.PurchId == vendPackingSlipTrans.OrigPurchid
        && purchLine.LineNumber == vendPackingSlipTrans.PurchaseLineLineNumber
        && purchLine.ItemId == vendAccruedPurchasesTmp.ItemId
    join pdsCatchWeightItem
        where pdsCatchWeightItem.ItemId == purchLine.ItemId;
    vendAccruedPurchasesTmp.ttscommit();
}

