    vendAccruedPurchasesTmp.ttsbegin();
    while select forupdate vendAccruedPurchasesTmp //where vendAccruedPurchasesTmp.PackingSlipSourceDocumentLine == 5646555759
    {
        select firstonly vendPackingSlipTrans
            where vendPackingSlipTrans.sourceDocumentline == vendAccruedPurchasesTmp.PackingSlipSourceDocumentLine
            join inventTable
            where inventTable.ItemId == vendPackingSlipTrans.ItemId;

